function mascot(code, className = "", interactive = false, hint = "") {
  const still = `<img src="${offline_paper_mascot[code]}" alt="" width="240" height="240" class="mascot-still">`;
  if (!interactive) return `<span class="mascot ${className}" aria-hidden="true">${still}</span>`;
  return `<button class="mascot mascot-toggle ${className}" type="button" data-action="expression" data-character="${code}"
    aria-label="${characters[code]} 표정 바꾸기" aria-pressed="false">${still}
    <img src="${offline_paper_smile[code]}" alt="" width="240" height="240" class="mascot-smile">
    ${hint ? `<span class="mascot-hint" aria-hidden="true">${hint}</span>
      <span class="mascot-sparks" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></span>` : ""}
  </button>`;
}

const speakerIcon = '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9v6h4l5 4V5L7 9H3Z"/><path d="M16 9a4 4 0 0 1 0 6m3-9a8 8 0 0 1 0 12"/></svg>';

function voiceButton(scene, label = "다시 듣기") {
  if (!offlineVoice[scene]) return "";
  return `<button class="voice-button screen-only" type="button" data-action="listen" data-value="${scene}" data-label="${label}">${speakerIcon}<span>${label}</span></button>`;
}

function voiceTools(scene) {
  if (!offlineVoice[scene]) return "";
  return `<div class="voice-tools screen-only">${voiceButton(scene)}
    <button class="voice-toggle" type="button" data-action="toggle-voice" data-value="${scene}">${voiceEnabled ? "소리 끄기" : "소리 켜기"}</button>
    <span class="voice-status" role="status"></span>
  </div>`;
}

function syncVoiceControls() {
  for (const button of app.querySelectorAll('[data-action="toggle-voice"]')) {
    button.textContent = voiceEnabled ? "소리 끄기" : "소리 켜기";
  }
  for (const button of app.querySelectorAll('[data-action="listen"]')) {
    const playing = button.dataset.value === playingScene;
    button.classList.toggle("voice-playing", playing);
    if (button.dataset.value === "cover") {
      const label = button.querySelector("span");
      if (label) label.textContent = playing ? "이야기 멈추기" : button.dataset.label;
      button.setAttribute("aria-pressed", String(playing));
    }
  }
}

function highlightSpokenChoice() {
  const times = typeof voiceCues === "undefined" ? [] : voiceCues[playingScene] ?? [];
  const current = voiceAudio.currentTime;
  app.querySelectorAll(".studio-options .option, .practice-options .option").forEach((option, index) => {
    const range = times[index];
    option.classList.toggle("spoken-choice", Boolean(range && current >= range[0] && current < range[1]));
  });
}

const coverMotionSrc = "assets/cover-motion.mp4";
const COVER_MOTION_LEAD = 0.4; // the motion starts 0.4s before the narration
// captions for the cover narration, in narration seconds
const coverCaptions = [
  [0.0, "안녕, 토끼야!"],
  [2.05, "같은 방인데, 너는 장난감이 먼저 보이고"],
  [6.15, "부모님은 다른 게 먼저 보일 수도 있어."],
  [9.5, "우리 서로 뭘 봤는지 알아볼까?"],
  [12.8, "그러고 나서 우리 집에 맞는 정리 방법을 같이 찾아보자!"],
];
let coverMotion = null;

// The motion plays in the picture only; the title and buttons stay usable,
// and the narration line replaces the description under the title.
function startCoverMotion() {
  stopCoverMotion(true);
  const stage = app.querySelector(".hero-stage");
  if (!stage) return;
  const text = stage.querySelector(".hero-text");
  const m = { stage, text, original: text?.textContent ?? "", line: -1, video: null, frame: 0 };
  if (text) text.classList.add("is-caption");
  if (motionAllowed()) {
    const art = stage.querySelector(".cover-art");
    const video = document.createElement("video");
    video.className = "cover-art cover-motion-video screen-only";
    Object.assign(video, { muted: true, playsInline: true, preload: "auto" });
    video.setAttribute("aria-hidden", "true");
    video.addEventListener("loadeddata", () => {
      if (coverMotion !== m) return;
      video.currentTime = Math.min(voiceAudio.currentTime + COVER_MOTION_LEAD, video.duration || 18);
      video.play().catch(() => {});
      requestAnimationFrame(() => video.classList.add("is-on"));
    }, { once: true });
    video.addEventListener("ended", () => { if (coverMotion === m) stopCoverMotion(); });
    video.src = coverMotionSrc;
    art?.after(video);
    m.video = video;
  }
  const tick = () => {
    if (coverMotion !== m) return;
    const now = voiceAudio.currentTime;
    if (playingScene === "cover" && !voiceAudio.paused) {
      const want = now + COVER_MOTION_LEAD;
      if (m.video && m.video.readyState >= 2 && Math.abs(m.video.currentTime - want) > 0.25) m.video.currentTime = want;
      let line = 0;
      while (line + 1 < coverCaptions.length && now >= coverCaptions[line + 1][0]) line++;
      if (line !== m.line && m.text) {
        m.line = line;
        m.text.textContent = coverCaptions[line][1];
        m.text.classList.remove("caption-in");
        void m.text.offsetWidth;
        m.text.classList.add("caption-in");
      }
    }
    m.frame = requestAnimationFrame(tick);
  };
  coverMotion = m;
  m.frame = requestAnimationFrame(tick);
}

function stopCoverMotion(immediate = false) {
  const m = coverMotion;
  if (!m) return;
  coverMotion = null;
  cancelAnimationFrame(m.frame);
  if (m.text) {
    m.text.textContent = m.original;
    m.text.classList.remove("is-caption", "caption-in");
  }
  const video = m.video;
  if (!video) return;
  const done = () => {
    video.pause();
    video.removeAttribute("src");
    video.load();
    video.remove();
  };
  if (immediate || !video.isConnected || !video.classList.contains("is-on") || !motionAllowed()) return done();
  video.addEventListener("transitionend", done, { once: true });
  video.classList.remove("is-on");
}

function stopNarration() {
  // a natural end keeps the motion running to its last frame, then it fades out
  if (coverMotion && !(playingScene === "cover" && voiceAudio.ended)) stopCoverMotion();
  playbackId++;
  voiceAudio.pause();
  playingScene = null;
  syncVoiceControls();
  highlightSpokenChoice();
}

function narrate(scene, tryAutomatically = false) {
  stopNarration();
  const status = app.querySelector(".voice-status");
  if (status) status.textContent = "";
  if (!voiceEnabled && !tryAutomatically) return;
  const source = offlineVoice[scene];
  if (!source) return;
  if (voiceAudio.getAttribute("src") !== source) voiceAudio.src = source;
  else voiceAudio.currentTime = 0;
  const id = playbackId;
  playingScene = scene;
  syncVoiceControls();
  if (scene === "cover") startCoverMotion();
  voiceAudio.play().catch(() => {
    if (id !== playbackId) return;
    stopNarration();
    if (status && !tryAutomatically) status.textContent = "소리가 안 들리면 다시 듣기를 눌러 주세요.";
  });
}

voiceAudio.addEventListener("timeupdate", highlightSpokenChoice);
voiceAudio.addEventListener("ended", () => {
  if (!voiceAudio.ended) return;
  const scene = playingScene;
  stopNarration();
  const practice = app.querySelector("#guide-practice:not([hidden])");
  const next = scene?.startsWith("guide-") && practice ? "#guide-practice [data-action=guided-setup]" :
    scene?.startsWith("guide-") ? ".guide-next button" : {
    intro: ".voice-intro .voice-next",
    "photo-ready": "#setup .voice-next",
    "look-ready": practice ? "#guide-practice [data-action=practice]" : ".quiz-nav .voice-next",
  }[scene];
  if (next) app.querySelector(next)?.scrollIntoView({ block: "nearest", behavior: motionAllowed() ? "smooth" : "instant" });
});
document.addEventListener("visibilitychange", () => {
  if (document.hidden) stopNarration();
});

