  if(phase==='intro'||o.introT<1){const k=Math.max(0,Math.min(1,(t-t0-.25-o.i*.11)/.75));o.introT=k;const e=k<1?1-Math.pow(1-k,3)*Math.cos(k*8)*1:1;oy+=(1-Math.min(1,e))*3.5;o.hide=k<=0}
