        if(W<1 || H<1) return;

  const wall=performance.now();
  if(!reduce)sceneTime+=Math.max(0,Math.min(.05,(wall-lastWall)/1000));lastWall=wall;
  const t=now(),dt=Math.max(0,Math.min(.05,t-last));last=t;
  const T=th();
  // camera
  const sway=reduce?0:.15;
  let tz=1;if(phase==='intro'){const k=Math.min(1,(t-t0)/.9);tz=.86+.14*(1-Math.pow(1-k,3));if(t-t0>1.4)phase='play'}
  if(phase==='gather')tz=1+Math.min(1,(t-tFin)/.8)*.04;
  zoom+=(tz-zoom)*(phase==='intro'?1:.12);
  yaw=.42+Math.sin(t*.33)*sway+(reduce?0:mx*.07)+(phase==='gather'?Math.min(1,(t-tFin)/.8)*.12:0);
  pit=.47+(reduce?0:Math.sin(t*.27)*.025)+(reduce?0:my*.03);
  cY=Math.cos(yaw);sY=Math.sin(yaw);cP=Math.cos(pit);sP=Math.sin(pit);
  layout();
  ctx.setTransform(DPR,0,0,DPR,0,0);ctx.clearRect(0,0,W,H);
  hits=[];
  // background
