  for(const s of STARS){ctx.fillStyle=T.star;ctx.globalAlpha=reduce?.65:.5+.5*Math.sin(t*1.3+s.ph);ctx.beginPath();ctx.arc(s.x*W,s.y*H,s.r,0,7);ctx.fill()}ctx.globalAlpha=1;
  const bob=reduce?0:Math.sin(t*.9)*.06;
  const pr=11*S,pc=[CX,CY+9.2*S];const pg=ctx.createRadialGradient(pc[0],pc[1]-pr*.7,pr*.1,pc[0],pc[1],pr);pg.addColorStop(0,rgb(T.planet,neon?.28:.42));pg.addColorStop(1,rgb(T.planet,0));
  ctx.fillStyle=pg;ctx.beginPath();ctx.arc(pc[0],pc[1],pr,0,7);ctx.fill();ctx.strokeStyle=T.planetLine;ctx.lineWidth=1;ctx.beginPath();ctx.arc(pc[0],pc[1],pr,0,7);ctx.stroke();
  // ambient cubes (behind)
  const ambDraw=front=>{for(const a of AMB){const y=a.y+(reduce?0:Math.sin(t*.8+a.ph)*.3),p=P(a.x,y,a.z);if((p[2]>0)!==front)continue;const c=a.c>.82&&phase!=='intro'?mix(hex(T.cube),hex(PALF[(a.ph*10|0)%8]),.55):hex(T.cube);miniCube(p[0],p[1],a.s*S,c,(reduce?0:Math.sin(t*.5+a.ph)*.4),envA*.9)}};
  ambDraw(false);
