async function shareResult(openShareSheet) {
  const field = document.querySelector("#share-summary");
  const status = document.querySelector("#share-status");
  try {
    if (openShareSheet) {
      await navigator.share({ title: "시선사이 · 우리 둘이 본 방", text: field.value });
      return;
    }
    await navigator.clipboard.writeText(field.value);
    status.textContent = "복사했어요. 받을 사람에게 붙여 넣어 보내세요.";
  } catch (error) {
    if (error.name === "AbortError") return;
    field.focus();
    field.select();
    status.textContent = "선택한 글을 복사해 받을 사람에게 보내세요.";
  }
}

const photoInput = (family) => app.querySelector(family ? "[data-family-photo]" : "[data-room]");

async function applyPhoto(file, input, stillCurrent) {
  const family = input.hasAttribute("data-family-photo");
  const url = URL.createObjectURL(file);
  const image = new Image();
  image.src = url;
  try {
    await image.decode();
  } catch {
    URL.revokeObjectURL(url);
    if (stillCurrent()) {
      const status = document.getElementById(family ? "family-photo-status" : "room-status");
      status.textContent = "사진을 열 수 없어요. JPG, PNG 또는 WebP 사진을 골라 주세요.";
      narrate("photo-error");
      input.value = "";
    }
    return;
  }
  if (!stillCurrent()) {
    URL.revokeObjectURL(url);
    return;
  }
  if (family) {
    if (state.familyPhoto) URL.revokeObjectURL(state.familyPhoto);
    state.familyPhoto = url;
    clearPrintImage();
    input.closest(".family-photo").outerHTML = photoSlot();
    preparePrintImage(app.querySelector("#print-options"));
    photoInput(true).focus({ preventScroll: true });
    return;
  }
  if (hasAnswers() && !window.confirm("사진을 바꾸고 처음부터 다시 답할까요?")) {
    URL.revokeObjectURL(url);
    input.value = "";
    return;
  }
  if (state.room) URL.revokeObjectURL(state.room);
  state.room = url;
  state.roomRatio = image.naturalWidth / image.naturalHeight;
  state.demo = false;
  clearAnswers();
  show("home", false);
  app.querySelector('[data-action="start"]').focus({ preventScroll: true });
  narrate("photo-ready");
}

function addImage(input) {
  const file = input.files[0];
  if (file) return applyPhoto(file, input, () => input.isConnected && input.files[0] === file);
}

function stopCamera() {
  activeCamera = null;
  cameraVideo.srcObject?.getTracks().forEach((track) => track.stop());
  cameraVideo.srcObject = null;
}

cameraDialog.addEventListener("close", () => {
  if (cameraDialog.open) return;
  stopCamera();
  if (playingScene?.startsWith("camera")) stopNarration();
});
window.addEventListener("pagehide", stopCamera);
window.addEventListener("pagehide", stopNarration);

async function openCamera(family) {
  stopNarration();
  const request = { family, input: photoInput(family) };
  activeCamera = request;
  cameraDialog.querySelector("h2").textContent = family ? "가족 사진 찍기" : "방 사진 찍기";
  shutter.disabled = true;
  cameraVideo.hidden = true;
  cameraStatus.textContent = "카메라를 여는 중이에요. 요청이 나오면 허용해 주세요.";
  cameraDialog.showModal();
  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: { ideal: family ? "user" : "environment" } }, audio: false,
    });
    if (activeCamera !== request || !cameraDialog.open) {
      stream.getTracks().forEach((track) => track.stop());
      return;
    }
    cameraVideo.srcObject = stream;
    cameraVideo.hidden = false;
    await cameraVideo.play();
    if (activeCamera !== request || !cameraDialog.open) return;
    cameraStatus.textContent = "화면을 보고 아래 버튼을 눌러요.";
    shutter.disabled = false;
    narrate("camera");
  } catch {
    if (activeCamera !== request || !cameraDialog.open) return;
    cameraVideo.srcObject?.getTracks().forEach((track) => track.stop());
    cameraVideo.srcObject = null;
    cameraVideo.hidden = true;
    cameraStatus.textContent = "카메라를 열 수 없어요. 기기의 사진을 골라서 넣을 수 있어요.";
    narrate("camera-error");
  }
}

function capturePhoto() {
  const request = activeCamera;
  if (!request || !cameraVideo.videoWidth || !cameraVideo.videoHeight) return;
  shutter.disabled = true;
  const canvas = document.createElement("canvas");
  canvas.width = cameraVideo.videoWidth;
  canvas.height = cameraVideo.videoHeight;
  canvas.getContext("2d").drawImage(cameraVideo, 0, 0);
  canvas.toBlob((blob) => {
    if (activeCamera !== request || !cameraDialog.open) return;
    if (!blob) {
      cameraStatus.textContent = "사진을 만들 수 없어요. 다시 찍어 주세요.";
      shutter.disabled = false;
      return;
    }
    cameraDialog.close();
    stopCamera();
    applyPhoto(blob, request.input, () => request.input.isConnected && !cameraDialog.open);
  }, "image/jpeg", .9);
}

